const ORIGIN='https://kanban.huongthiennature.com',enc=new TextEncoder();
const hex=b=>Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join('');
const bytes=h=>Uint8Array.from(h.match(/../g)||[],s=>parseInt(s,16));
const random=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
const hash=async s=>hex(await crypto.subtle.digest('SHA-256',enc.encode(s)));
async function passwordHash(password,salt=hex(crypto.getRandomValues(new Uint8Array(16)))){const k=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']);return salt+':'+hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes(salt),iterations:100000,hash:'SHA-256'},k,256));}
async function passwordMatches(password,stored){const candidate=await passwordHash(password,stored.split(':')[0]);let diff=candidate.length^stored.length;for(let i=0;i<stored.length;i++)diff|=(candidate.charCodeAt(i)||0)^stored.charCodeAt(i);return diff===0;}
const json=(x,status=200,headers={})=>Response.json(x,{status,headers:{'Cache-Control':'no-store',...headers}});
const fail=(message,status=400)=>{throw Object.assign(new Error(message),{status});};
async function limited(db,key,max=12){const now=Date.now(),r=await db.prepare('INSERT INTO rate_limits(key,count,expires) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN expires<? THEN 1 ELSE count+1 END,expires=CASE WHEN expires<? THEN excluded.expires ELSE expires END RETURNING count').bind(key,now+900000,now,now).first();if(r.count>max)fail('Bạn thao tác quá nhiều. Vui lòng thử lại sau 15 phút.',429);}
async function mail(env,to,subject,text,key){const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify({from:'Zen Studio <no-reply@huongthiennature.com>',to:[to],subject,text})});if(!response.ok)throw new Error('Không gửi được email. Vui lòng thử lại sau.');}
async function tokenMail(env,user,kind){const token=random(),digest=await hash(token),now=Date.now();await env.DB.prepare('INSERT INTO tokens(token_hash,user_id,kind,expires) VALUES(?,?,?,?)').bind(digest,user.id,kind,now+(kind==='reset'?1800000:86400000)).run();const link=ORIGIN+'/#'+kind+'='+token;await mail(env,user.email,kind==='reset'?'Đặt lại mật khẩu Zen Studio':'Xác minh email Zen Studio',(kind==='reset'?'Liên kết đặt lại mật khẩu có hiệu lực 30 phút: ':'Xác minh email trong 24 giờ: ')+link+'\nNếu bạn không yêu cầu, hãy bỏ qua email này.',digest);}
async function session(request,env){const token=request.headers.get('Cookie')?.match(/(?:^|; )zen_session=([a-f0-9]{64})/)?.[1];if(!token)fail('Vui lòng đăng nhập.',401);const u=await env.DB.prepare('SELECT u.id,u.email,u.email_reminders FROM users u JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires>?').bind(await hash(token),Date.now()).first();if(!u)fail('Phiên đăng nhập đã hết hạn.',401);return u;}
function validWorkspace(d){if(!d||d.schema!==1||!Array.isArray(d.projects)||d.projects.length>100)return false;const ids=new Set(),id=x=>typeof x==='string'&&x.length<100&&!ids.has(x)&&!!ids.add(x),str=(x,n)=>typeof x==='string'&&x.length<=n;return d.projects.every(p=>id(p.id)&&str(p.name,100)&&p.name.trim()&&str(p.description,2000)&&/^#[a-f0-9]{6}$/i.test(p.color)&&str(p.icon,8)&&Array.isArray(p.columns)&&p.columns.length>=4&&p.columns.length<=20&&['Idea','List','Doing','Done'].every(c=>p.columns.includes(c))&&new Set(p.columns).size===p.columns.length&&p.columns.every(c=>str(c,40)&&c.trim())&&Array.isArray(p.tasks)&&p.tasks.length<=2000&&p.tasks.every(t=>id(t.id)&&str(t.title,200)&&t.title.trim()&&str(t.description,5000)&&str(t.tag,40)&&str(t.due,10)&&(!t.due||/^\d{4}-\d{2}-\d{2}$/.test(t.due))&&p.columns.includes(t.col)&&(!t.labels||(Array.isArray(t.labels)&&t.labels.length<=20&&t.labels.every(l=>l&&str(l.name,40)&&/^#[a-f0-9]{6}$/i.test(l.color))))&&Array.isArray(t.checks)&&t.checks.length<=200&&t.checks.every(c=>id(c.id)&&str(c.text,300)&&typeof c.done==='boolean')&&(t.col!=='Done'||t.checks.every(c=>c.done))));}
async function body(request){if(Number(request.headers.get('Content-Length')||0)>2000000)fail('Dữ liệu quá lớn.',413);const reader=request.body?.getReader();if(!reader) return {};let length=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>2000000){await reader.cancel();fail('Dữ liệu quá lớn.',413);}chunks.push(value);}const data=new Uint8Array(length);let pos=0;for(const c of chunks){data.set(c,pos);pos+=c.length;}try{return JSON.parse(new TextDecoder().decode(data));}catch{fail('Dữ liệu không hợp lệ.');}}
function pushHost(endpoint){try{const u=new URL(endpoint);return u.protocol==='https:'&&!u.username&&!u.password&&u.port===''&&(['fcm.googleapis.com','updates.push.services.mozilla.com','web.push.apple.com'].includes(u.hostname)||u.hostname.endsWith('.notify.windows.com'));}catch{return false;}}
async function api(request,env){try{const path=new URL(request.url).pathname;if(!['GET','POST','PUT','DELETE'].includes(request.method))return json({error:'Method not allowed'},405);if(request.method!=='GET'&&(request.headers.get('Origin')!==ORIGIN||!request.headers.get('Content-Type')?.includes('application/json')))fail('Yêu cầu không hợp lệ.',403);const db=env.DB,ip=request.headers.get('CF-Connecting-IP')||'unknown';if(path==='/api/me'){const u=await session(request,env);return json({user:u});}if(path==='/api/push-key'){await session(request,env);return json({key:env.VAPID_PUBLIC});}
if(['/api/register','/api/login','/api/forgot','/api/reset','/api/verify','/api/resend'].includes(path)){if(request.method!=='POST')fail('Method not allowed',405);await limited(db,'auth:'+await hash(ip),35);const b=await body(request),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');if(['register','login','forgot','resend'].some(x=>path==='/api/'+x)&&(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254))fail('Email không hợp lệ.');if(path==='/api/register'){if(password.length<10||password.length>128)fail('Mật khẩu cần từ 10 đến 128 ký tự.');await limited(db,'mail:'+await hash(email),4);let u=await db.prepare('SELECT id,email,verified FROM users WHERE email=?').bind(email).first();if(!u){u={id:crypto.randomUUID(),email};await db.prepare('INSERT INTO users(id,email,password_hash,created) VALUES(?,?,?,?)').bind(u.id,email,await passwordHash(password),Date.now()).run();}if(!u.verified)await tokenMail(env,u,'verify');return json({message:'Yêu cầu đăng ký đã được tiếp nhận. Hãy kiểm tra hộp thư đến và Thư rác để tìm email “Xác minh email Zen Studio”, rồi mở liên kết và bấm “Xác minh email” để hoàn tất. Nếu email đã có tài khoản, hãy đăng nhập hoặc dùng Quên mật khẩu.'});}
if(path==='/api/login'){if(password.length>128)fail('Email hoặc mật khẩu chưa đúng.',401);await limited(db,'login:'+await hash(email),10);const u=await db.prepare('SELECT * FROM users WHERE email=?').bind(email).first();if(!u){await passwordHash(password);fail('Email hoặc mật khẩu chưa đúng.',401);}if(password.length>128||!await passwordMatches(password,u.password_hash))fail('Email hoặc mật khẩu chưa đúng.',401);if(!u.verified)fail('Vui lòng xác minh email trước khi đăng nhập. Bạn có thể gửi lại email xác minh.',403);const token=random();await db.prepare('INSERT INTO sessions(token_hash,user_id,expires) VALUES(?,?,?)').bind(await hash(token),u.id,Date.now()+604800000).run();return json({ok:true},200,{'Set-Cookie':'zen_session='+token+'; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=604800'});}
if(path==='/api/forgot'||path==='/api/resend'){await limited(db,'mail:'+await hash(email),4);const u=await db.prepare('SELECT id,email,verified FROM users WHERE email=?').bind(email).first();if(u&&(path==='/api/forgot'||!u.verified))await tokenMail(env,u,path==='/api/forgot'?'reset':'verify');return json({message:'Nếu email phù hợp, liên kết đã được gửi. Hãy kiểm tra cả thư rác.'});}
if(path==='/api/verify'||path==='/api/reset'){const digest=await hash(String(b.token||'')),kind=path==='/api/reset'?'reset':'verify';if(kind==='reset'&&(password.length<10||password.length>128))fail('Mật khẩu cần từ 10 đến 128 ký tự.');const t=await db.prepare('SELECT * FROM tokens WHERE token_hash=? AND kind=? AND expires>?').bind(digest,kind,Date.now()).first();if(!t)fail('Liên kết hết hạn hoặc đã được sử dụng.');const newHash=kind==='reset'?await passwordHash(password):null;const mutation=kind==='reset'?db.prepare('UPDATE users SET password_hash=? WHERE id=? AND EXISTS(SELECT 1 FROM tokens WHERE token_hash=?)').bind(newHash,t.user_id,digest):db.prepare('UPDATE users SET verified=1 WHERE id=? AND EXISTS(SELECT 1 FROM tokens WHERE token_hash=?)').bind(t.user_id,digest);await db.batch([mutation,db.prepare('DELETE FROM tokens WHERE user_id=? AND kind=?').bind(t.user_id,kind),...(kind==='reset'?[db.prepare('DELETE FROM sessions WHERE user_id=?').bind(t.user_id)]:[])]);return json({message:kind==='reset'?'Đã đặt lại mật khẩu. Vui lòng đăng nhập.':'Email đã được xác minh. Bạn có thể đăng nhập.'});}}
const u=await session(request,env);if(path==='/api/logout'&&request.method==='POST'){const token=request.headers.get('Cookie')?.match(/zen_session=([a-f0-9]{64})/)?.[1];await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await hash(token)).run();return json({ok:true},200,{'Set-Cookie':'zen_session=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0'});}
if(path==='/api/workspace'){if(request.method==='GET'){const row=await db.prepare('SELECT data,revision FROM workspaces WHERE user_id=?').bind(u.id).first();return json(row?{data:JSON.parse(row.data),revision:row.revision}:{data:{schema:1,projects:[]},revision:0});}if(request.method==='PUT'){const b=await body(request);if(!Number.isInteger(b.revision)||b.revision<0||!validWorkspace(b.data))fail('Dữ liệu dự án không hợp lệ.');const raw=JSON.stringify(b.data);await db.prepare('INSERT OR IGNORE INTO workspaces(user_id,data,revision) VALUES(?,?,0)').bind(u.id,'{"schema":1,"projects":[]}').run();const result=await db.prepare('UPDATE workspaces SET data=?,revision=revision+1 WHERE user_id=? AND revision=? RETURNING revision').bind(raw,u.id,b.revision).first();if(!result)return json({error:'Dữ liệu đã đổi trên thiết bị khác. Bản chỉnh sửa của bạn được giữ lại để xử lý xung đột.'},409);return json({revision:result.revision});}}
if(path==='/api/preferences'&&request.method==='PUT'){const b=await body(request);await db.prepare('UPDATE users SET email_reminders=? WHERE id=?').bind(b.emailReminders===true?1:0,u.id).run();return json({ok:true});}
if(path==='/api/push'&&request.method==='POST'){const b=await body(request);if(!pushHost(b.endpoint))fail('Dịch vụ thông báo không được hỗ trợ.');await db.prepare('INSERT INTO subscriptions(endpoint,user_id) VALUES(?,?) ON CONFLICT(endpoint) DO UPDATE SET user_id=excluded.user_id').bind(b.endpoint,u.id).run();return json({ok:true});}if(path==='/api/push'&&request.method==='DELETE'){const b=await body(request);await db.prepare('DELETE FROM subscriptions WHERE user_id=? AND endpoint=?').bind(u.id,String(b.endpoint||'')).run();return json({ok:true});}return json({error:'Not found'},404);
}catch(e){return json({error:e.status?e.message:'Máy chủ chưa xử lý được yêu cầu. Vui lòng thử lại.'},e.status||503);}}
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
async function sendPush(env,endpoint){if(!pushHost(endpoint))return;const header=b64(enc.encode(JSON.stringify({typ:'JWT',alg:'ES256'}))),payload=b64(enc.encode(JSON.stringify({aud:new URL(endpoint).origin,exp:Math.floor(Date.now()/1000)+3600,sub:'mailto:no-reply@huongthiennature.com'}))),input=header+'.'+payload;const key=await crypto.subtle.importKey('jwk',JSON.parse(env.VAPID_PRIVATE),{name:'ECDSA',namedCurve:'P-256'},false,['sign']);const signature=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,enc.encode(input));const response=await fetch(endpoint,{method:'POST',headers:{TTL:'86400',Authorization:'vapid t='+input+'.'+b64(signature)+', k='+env.VAPID_PUBLIC}});if([404,410].includes(response.status)){await env.DB.prepare('DELETE FROM subscriptions WHERE endpoint=?').bind(endpoint).run();return;}if(!response.ok)throw Error('Push rejected');}
async function daily(env){const db=env.DB,day=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});const users=(await db.prepare('SELECT u.id,u.email,u.email_reminders,w.data FROM users u JOIN workspaces w ON w.user_id=u.id WHERE u.verified=1').all()).results;for(const u of users){try{const tasks=JSON.parse(u.data).projects.flatMap(p=>p.tasks),due=tasks.filter(t=>t.due&&t.due<=day&&t.col!=='Done');if(!due.length)continue;for(const channel of ['email','push']){if(channel==='email'&&!u.email_reminders)continue;const previous=await db.prepare('SELECT status FROM deliveries WHERE user_id=? AND day=? AND channel=?').bind(u.id,day,channel).first();if(previous?.status==='sent')continue;try{if(channel==='email')await mail(env,u.email,'Nhắc việc hằng ngày · Zen Studio',`Bạn có ${due.length} công việc đến hạn hoặc quá hạn.\nMở ${ORIGIN} để xem.\nTắt email nhắc việc trong mục Tài khoản & thông báo.`,u.id+'-'+day);else{const subs=(await db.prepare('SELECT endpoint FROM subscriptions WHERE user_id=?').bind(u.id).all()).results;for(const sub of subs)await sendPush(env,sub.endpoint);}await db.prepare("INSERT INTO deliveries(user_id,day,channel,status) VALUES(?,?,?,'sent') ON CONFLICT(user_id,day,channel) DO UPDATE SET status='sent'").bind(u.id,day,channel).run();}catch{console.log(JSON.stringify({event:'reminder_failed',channel}));}}}catch{console.log(JSON.stringify({event:'reminder_user_failed'}));}}await db.batch([db.prepare('DELETE FROM sessions WHERE expires<?').bind(Date.now()),db.prepare('DELETE FROM tokens WHERE expires<?').bind(Date.now()),db.prepare('DELETE FROM rate_limits WHERE expires<?').bind(Date.now()),db.prepare('DELETE FROM deliveries WHERE day<?').bind(new Date(Date.now()-30*86400000).toISOString().slice(0,10))]);}

